import React, { useState } from 'react';

export default function BlocoEtapaVisual({ etapaId = 1, titulo = null }) {
  const [mensagem, setMensagem] = useState('');
  const [opcoes, setOpcoes] = useState([]);
  const [usarOpcoes, setUsarOpcoes] = useState(false);
  const [subEtapas, setSubEtapas] = useState({});

  const adicionarOpcao = () => {
    const nova = { texto: '', acao: 'mensagem', destino: '', id: Date.now() };
    setOpcoes([...opcoes, nova]);
  };

  const atualizarOpcao = (index, campo, valor) => {
    const novas = [...opcoes];
    novas[index][campo] = valor;
    setOpcoes(novas);

    // Se definir ação com subetapa, inicializa subetapa
    if (campo === 'acao' && valor !== 'redirecionar') {
      const chave = 'opcao_' + index;
      if (!subEtapas[chave]) {
        setSubEtapas({ ...subEtapas, [chave]: true });
      }
    }
  };

  return (
    <div className="border rounded p-4 bg-white shadow mb-6 max-w-2xl mx-auto">
      <h2 className="font-bold text-lg mb-4">
        {titulo || `Etapa #${etapaId}`}
      </h2>

      <label className="block text-sm font-medium mb-1">Mensagem para o cliente:</label>
      <textarea
        value={mensagem}
        onChange={(e) => setMensagem(e.target.value)}
        placeholder="Digite a mensagem dessa etapa..."
        rows={3}
        className="w-full border rounded p-2 mb-4"
      />

      <label className="inline-flex items-center mb-4">
        <input
          type="checkbox"
          checked={usarOpcoes}
          onChange={() => setUsarOpcoes(!usarOpcoes)}
          className="mr-2"
        />
        Adicionar opções interativas
      </label>

      {usarOpcoes && (
        <div className="space-y-3">
          {opcoes.map((opcao, index) => (
            <div key={index} className="border p-3 rounded bg-gray-50">
              <div className="flex gap-2 mb-2">
                <input
                  type="text"
                  placeholder={`Texto da opção ${index + 1}`}
                  value={opcao.texto}
                  onChange={(e) => atualizarOpcao(index, 'texto', e.target.value)}
                  className="border rounded p-2 w-1/2"
                />
                <select
                  value={opcao.acao}
                  onChange={(e) => atualizarOpcao(index, 'acao', e.target.value)}
                  className="border rounded p-2 w-1/3"
                >
                  <option value="mensagem">➡️ Nova mensagem</option>
                  <option value="etapa">🔁 Ir para etapa</option>
                  <option value="redirecionar">☎️ Redirecionar</option>
                </select>
              </div>

              {opcao.acao !== 'mensagem' && (
                <input
                  type="text"
                  placeholder={opcao.acao === 'etapa' ? 'Etapa destino' : 'Número WhatsApp'}
                  value={opcao.destino}
                  onChange={(e) => atualizarOpcao(index, 'destino', e.target.value)}
                  className="border rounded p-2 w-full"
                />
              )}

              {opcao.acao !== 'redirecionar' && subEtapas['opcao_' + index] && (
                <div className="mt-4 ml-4 border-l-4 border-blue-400 pl-4">
                  <BlocoEtapaVisual
                    etapaId={`${etapaId}.${index + 1}`}
                    titulo={`Opção ${index + 1} - ${opcao.texto || 'Fluxo personalizado'}`}
                  />
                </div>
              )}
            </div>
          ))}

          <button
            onClick={adicionarOpcao}
            className="bg-blue-500 text-white text-sm px-3 py-1 rounded hover:bg-blue-600"
          >
            + Adicionar Opção
          </button>
        </div>
      )}
    </div>
  );
}
